	@Test
	void nativeAndLegacyCachesKeepTheirOwnBackingMemory() throws Exception {
		try (Environment env = new Environment(directory, 0)) {
			env.put(0, 32);
			try (ReadTxn txn = env.read();
					MemoryStack stack = stackPush();
					LmdbPageCardinalityEstimator estimator = new LmdbPageCardinalityEstimator(env.dataPath.toFile(),
							env.handle)) {
				PointerBuffer pointer = stack.mallocPointer(1);
				check(mdb_cursor_open(txn.handle(), env.dbi, pointer));
				long cursor = pointer.get(0);
				try {
					MDBVal nativeKey = MDBVal.malloc(stack);
					MDBVal nativeValue = MDBVal.malloc(stack);
					for (boolean nativeReads : new boolean[] { false, true, true, false }) {
						int[] visits = { 0 };
						GroupMatcher matcher = new GroupMatcher(key(0), new boolean[] { false, false, false, false }) {
							@Override
							public boolean matches(ByteBuffer candidate) {
								nativeKey.mv_data(candidate);
								check(mdb_cursor_get(cursor, nativeKey, nativeValue, MDB_SET_KEY));
								assertEquals(nativeReads, memAddress(candidate) == memAddress(nativeKey.mv_data()),
										"Estimator matcher must receive the requested backing memory, including cache hits");
								visits[0]++;
								return true;
							}
						};
						long count = nativeReads ? estimate(estimator, txn.handle(), matcher)
								: estimator.estimateEntries(txn.id(), "statements", key(0), 4, key(9), 4, matcher);
						assertEquals(10, count);
						assertEquals(10, visits[0]);
					}
				} finally {
					mdb_cursor_close(cursor);
				}
			}
		}
	}

