	private static GroupMatcher blockingMatcher(CountDownLatch entered, CountDownLatch release) {
		return new GroupMatcher(key(0), new boolean[] { false, false, false, false }) {
			@Override
			public boolean matches(ByteBuffer other) {
				entered.countDown();
				try {
					assertTrue(release.await(10, TimeUnit.SECONDS), "Test must release the page reader");
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new AssertionError(e);
				}
				return true;
			}
		};
	}

	private static long totalEntries(LmdbPageCardinalityEstimator estimator, long txn) throws IOException {
		try (var view = estimator.readTransaction(txn)) {
			return view.totalEntries("statements");
		}
	}

	private static long estimate(LmdbPageCardinalityEstimator estimator, long txn, GroupMatcher matcher)
			throws IOException {
		byte[] min = key(0);
		byte[] max = key(9);
		try (var view = estimator.readTransaction(txn)) {
			return view.estimateEntries("statements", min, min.length, max, max.length, matcher, 1);
		}
	}

	private static byte[] key(int ordinal) {
		return new byte[] { (byte) (1 + ordinal / 100), (byte) (1 + ordinal % 100), 1, 1 };
	}

	private static void check(int result) {
		assertEquals(MDB_SUCCESS, result, () -> mdb_strerror(result));
	}

	private record ReadTxn(long handle) implements AutoCloseable {
		long id() {
			return mdb_txn_id(handle);
		}

		@Override
		public void close() {
			mdb_txn_abort(handle);
		}
	}

	private static final class Environment implements AutoCloseable {
		final long handle;
		final Path dataPath;
		final int dbi;

		Environment(Path location, int flags) {
			dataPath = (flags & MDB_NOSUBDIR) != 0 ? location : location.resolve("data.mdb");
			try (MemoryStack stack = stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				check(mdb_env_create(pointer));
				handle = pointer.get(0);
				try {
					check(mdb_env_set_mapsize(handle, 64L << 20));
					check(mdb_env_set_maxdbs(handle, 4));
					check(mdb_env_open(handle, location.toString(), MDB_NOTLS | flags, 0664));
					check(mdb_txn_begin(handle, NULL, flags & MDB_RDONLY, pointer));
					long txn = pointer.get(0);
					IntBuffer db = stack.mallocInt(1);
					try {
						check(mdb_dbi_open(txn, "statements", (flags & MDB_RDONLY) == 0 ? MDB_CREATE : 0, db));
					} catch (Throwable failure) {
						mdb_txn_abort(txn);
						throw failure;
					}
					check(mdb_txn_commit(txn));
					dbi = db.get(0);
				} catch (Throwable failure) {
					mdb_env_close(handle);
					throw failure;
				}
			}
		}

		ReadTxn read() {
			try (MemoryStack stack = stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				check(mdb_txn_begin(handle, NULL, MDB_RDONLY, pointer));
				return new ReadTxn(pointer.get(0));
			}
		}

		void put(int start, int end) {
			try (MemoryStack stack = stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				check(mdb_txn_begin(handle, NULL, 0, pointer));
				long txn = pointer.get(0);
				try {
					ByteBuffer keyBytes = stack.malloc(4);
					MDBVal key = MDBVal.malloc(stack).mv_data(keyBytes);
					MDBVal value = MDBVal.malloc(stack).mv_data(stack.calloc(64));
					for (int ordinal = start; ordinal < end; ordinal++) {
						keyBytes.clear().put(key(ordinal)).flip();
						check(mdb_put(txn, dbi, key, value, 0));
					}
				} catch (Throwable failure) {
					mdb_txn_abort(txn);
					throw failure;
				}
				check(mdb_txn_commit(txn));
			}
		}

		@Override
		public void close() {
			mdb_env_close(handle);
		}
	}
